head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25105";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — spotIsuTrdMktTpCd, bndListStatYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25105.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_124", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm1.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시책임자 : " + String(dma_bondDisclsChrgNm1.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_126", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm2.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시담당자 : " + String(dma_bondDisclsChrgNm2.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_128", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm3.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시실무자 : " + String(dma_bondDisclsChrgNm3.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_124_r1", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm1.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시책임자 : " + String(dma_bondDisclsChrgNm1.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_126_r1", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm2.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시담당자 : " + String(dma_bondDisclsChrgNm2.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_128_r1", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm3.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시실무자 : " + String(dma_bondDisclsChrgNm3.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_124_r2", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm1.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시책임자 : " + String(dma_bondDisclsChrgNm1.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_126_r2", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm2.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시담당자 : " + String(dma_bondDisclsChrgNm2.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_128_r2", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm3.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시실무자 : " + String(dma_bondDisclsChrgNm3.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_124_r3", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm1.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시책임자 : " + String(dma_bondDisclsChrgNm1.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_126_r3", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm2.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시담당자 : " + String(dma_bondDisclsChrgNm2.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } },
        { childId: "td_128_r3", attr: "__html", fn: function () { return ([String(dma_bondDisclsChrgNm3.get("chrgNm"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("&nbsp;&nbsp;&nbsp;&nbsp;<font color=\"blue\">* 당해법인 채권공시실무자 : " + String(dma_bondDisclsChrgNm3.get("chrgNm")) + "</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_otherwise_51", fn: function(){ return (!((1===1) || (1===2) || (1===3))); } }, { id: "c_when_53_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_54", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_when_123", fn: function(){ return (1 === 1 && !(String(((dma_bondDisclsChrgNm1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm1.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm1.chrgNm"); })()))).length === 0)); } }, { id: "c_when_125", fn: function(){ return (1 === 2 && !(String(((dma_bondDisclsChrgNm2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm2.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm2.chrgNm"); })()))).length === 0)); } }, { id: "c_when_127", fn: function(){ return (1 === 3 && !(String(((dma_bondDisclsChrgNm3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm3.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm3.chrgNm"); })()))).length === 0)); } }, { id: "if_bndListStatYn", fn: function(){ return ((dma_pageContext.get("bndListStatYn") ?? "") === 'Y'); } }, { id: "c_when_45_r1_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_46_r1", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_otherwise_51_r1", fn: function(){ return (!((2===1) || (2===2) || (2===3))); } }, { id: "c_when_53_r1_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_54_r1", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_when_123_r1", fn: function(){ return (2 === 1 && !(String(((dma_bondDisclsChrgNm1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm1.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm1.chrgNm"); })()))).length === 0)); } }, { id: "c_when_125_r1", fn: function(){ return (2 === 2 && !(String(((dma_bondDisclsChrgNm2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm2.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm2.chrgNm"); })()))).length === 0)); } }, { id: "c_when_127_r1", fn: function(){ return (2 === 3 && !(String(((dma_bondDisclsChrgNm3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm3.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm3.chrgNm"); })()))).length === 0)); } }, { id: "if_bndListStatYn_r1", fn: function(){ return ((dma_pageContext.get("bndListStatYn") ?? "") === 'Y'); } }, { id: "c_when_49_r2_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_50_r2", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_otherwise_51_r2", fn: function(){ return (!((3===1) || (3===2) || (3===3))); } }, { id: "c_when_53_r2_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_54_r2", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_when_123_r2", fn: function(){ return (3 === 1 && !(String(((dma_bondDisclsChrgNm1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm1.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm1.chrgNm"); })()))).length === 0)); } }, { id: "c_when_125_r2", fn: function(){ return (3 === 2 && !(String(((dma_bondDisclsChrgNm2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm2.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm2.chrgNm"); })()))).length === 0)); } }, { id: "c_when_127_r2", fn: function(){ return (3 === 3 && !(String(((dma_bondDisclsChrgNm3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm3.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm3.chrgNm"); })()))).length === 0)); } }, { id: "if_bndListStatYn_r2", fn: function(){ return ((dma_pageContext.get("bndListStatYn") ?? "") === 'Y'); } }, { id: "c_otherwise_51_r3", fn: function(){ return (!((4===1) || (4===2) || (4===3))); } }, { id: "c_when_53_r3_txt", fn: function(){ return ((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'); } }, { id: "c_otherwise_54_r3", fn: function(){ return (!(((dma_pageContext.get("spotIsuTrdMktTpCd") ?? "") ==='2'))); } }, { id: "c_when_123_r3", fn: function(){ return (4 === 1 && !(String(((dma_bondDisclsChrgNm1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm1.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm1.chrgNm"); })()))).length === 0)); } }, { id: "c_when_125_r3", fn: function(){ return (4 === 2 && !(String(((dma_bondDisclsChrgNm2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm2.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm2.chrgNm"); })()))).length === 0)); } }, { id: "c_when_127_r3", fn: function(){ return (4 === 3 && !(String(((dma_bondDisclsChrgNm3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm3.chrgNm"); })())) == null ? '' : ((dma_bondDisclsChrgNm3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "bondDisclsChrgNm3.chrgNm"); })()))).length === 0)); } }, { id: "if_bndListStatYn_r3", fn: function(){ return ((dma_pageContext.get("bndListStatYn") ?? "") === 'Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

