/**
 * @method
 * @name setZipCode_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setZipCode).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setZipCode.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };

/**
 * @method
 * @name isZipCodeInput
 * @description 우편번호 입력 검사 — 공백·'-' 를 뺀 나머지가 숫자만인지(as-is 공통 fn_ChkZipCd, 아니면 포커스)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Boolean} 숫자만이면 true
 * @hidden N
 */
scwin.isZipCodeInput = function (comp) {
    if (!comp || typeof comp.getValue !== "function") { return true; }
    const v = String(comp.getValue() ?? "").replace(/\s/g, "").replace("-", "");
    if (!/^\d*$/.test(v)) { comp.focus(); return false; }
    return true;
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk/fn_IsNull 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @param {*} fieldName 항목명(생략 시 컴포넌트 title → id)
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp, fieldName) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = fieldName || (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};
